const entry=document.querySelector('#entry');
const brand='<div class="entry-logo">AdvanCE<span>!</span></div>';
let demoProfile=null;try{demoProfile=JSON.parse(localStorage.getItem('advance-demo-profile')||'null')}catch{}
function enterHome(profile){if(profile?.name){document.querySelector('#username').textContent=profile.name;try{localStorage.setItem('advance-demo-name',profile.name)}catch{}}if(profile?.bio!==undefined)document.querySelector('#signature').textContent=profile.bio;if(profile?.avatar){const avatar=document.querySelector('.profile .avatar');avatar.textContent=profile.avatar;avatar.classList.add('avatar-emoji')}entry.hidden=true;document.body.classList.remove('booting')}
function loginPage(){entry.innerHTML='<div class="login-brand entry-logo">AdvanCE<span>!</span></div><form class="login-shell"><div class="login-box"><div class="login-tabs" role="tablist" aria-label="登录方式"><button type="button" role="tab" aria-selected="true" id="existing">已有账号</button><button type="button" role="tab" aria-selected="false" id="create">创建账号</button></div><div class="login-fields"><label id="accountLabel" for="account">账号</label><input id="account" autocomplete="username" placeholder="填写账号" required maxlength="30"><label id="passwordLabel" for="password">密码</label><input id="password" type="password" autocomplete="current-password" placeholder="填写密码" required minlength="6"></div></div><p class="login-error" aria-live="polite"></p><button class="login-confirm" type="submit">确认</button><p class="login-note">原型演示：填写任意账号及至少 6 位演示密码即可体验。<br>不验证真实账号，不保存密码。</p></form>';let create=false;const account=document.querySelector('#account'),password=document.querySelector('#password');function mode(value){create=value;document.querySelector('#existing').setAttribute('aria-selected',!value);document.querySelector('#create').setAttribute('aria-selected',value);document.querySelector('#accountLabel').textContent=value?'昵称':'账号';account.placeholder=value?'填写昵称':'填写账号';document.querySelector('#passwordLabel').textContent=value?'密码设置':'密码';password.placeholder=value?'设置至少 6 位演示密码':'填写密码';password.autocomplete=value?'new-password':'current-password';password.value=''}document.querySelector('#existing').onclick=()=>mode(false);document.querySelector('#create').onclick=()=>mode(true);entry.querySelector('.login-confirm').onclick=e=>{e.preventDefault();entry.querySelector('form').requestSubmit()};entry.querySelector('form').onsubmit=e=>{e.preventDefault();if(!account.value.trim()){entry.querySelector('.login-error').textContent='请填写'+(create?'昵称':'账号');account.focus();return}demoProfile={...(demoProfile||{}),name:account.value.trim()};try{localStorage.setItem('advance-demo-profile',JSON.stringify(demoProfile));localStorage.setItem('advance-demo-name',demoProfile.name)}catch{}password.value='';if(localStorage.getItem('advance-onboarding-seen')==='1')enterHome(demoProfile);else showOnboarding(demoProfile)}}
// App entry always presents the requested sequence; internal back navigation skips it.
const returnHome=new URLSearchParams(location.search).get('view')==='home';
const previewGuide=new URLSearchParams(location.search).get('guide')==='preview';
if(returnHome){enterHome(demoProfile);history.replaceState(null,'',location.pathname)}else{entry.innerHTML='<div class="splash">'+brand+'</div>';setTimeout(()=>{if(previewGuide)showOnboarding(demoProfile,true);else loginPage()},1000)}
